// Jeu de données fictif, conçu pour documenter le format sans utiliser d’IA.
const reunionFictive = {
  reunion_id: 'REU-EX-001',
  titre: 'Réunion de démonstration — données fictives',
  notes_fictives: [
    'ACTION | Préparer le plan de test | Camille | 2026-11-15',
    'DECISION | Le prototype reste hors production jusqu’à validation humaine.',
    'ACTION | Centraliser les retours de test | Morgan | 2026-11-22'
  ].join('\n'),
  format_documente: {
    action: 'ACTION | tâche | responsable | YYYY-MM-DD',
    decision: 'DECISION | texte'
  },
  avertissement: 'Exemple fictif : ne crée aucune tâche réelle.'
};

return [{ json: reunionFictive }];

// Extraction déterministe : seules les lignes ACTION et DECISION sont interprétées.
const propositions = [];

for (const item of $input.all()) {
  const source = item.json || {};
  const lignes = String(source.notes_fictives || '').split(/\r?\n/);
  for (const ligneBrute of lignes) {
    const ligne = ligneBrute.trim();
    if (!ligne) continue;
    const morceaux = ligne.split('|').map((morceau) => morceau.trim());
    const type = String(morceaux[0] || '').toLocaleUpperCase('fr-FR');

    if (type === 'ACTION') {
      propositions.push({
        json: {
          type: 'action',
          reunion_id: source.reunion_id || null,
          titre_reunion: source.titre || null,
          tache: morceaux[1] || null,
          responsable: morceaux[2] || null,
          echeance: morceaux[3] || null,
          ligne_source: ligne,
          proposition_uniquement: true
        }
      });
    } else if (type === 'DECISION') {
      propositions.push({
        json: {
          type: 'decision',
          reunion_id: source.reunion_id || null,
          titre_reunion: source.titre || null,
          texte: morceaux.slice(1).join(' | ') || null,
          ligne_source: ligne,
          proposition_uniquement: true
        }
      });
    }
  }
}

return propositions;

// Validation stricte avant toute validation humaine ; aucune intégration de tâches n’est appelée.
const estDateISOValide = (valeur) => {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(String(valeur || ''))) return false;
  const [annee, mois, jour] = valeur.split('-').map(Number);
  const date = new Date(Date.UTC(annee, mois - 1, jour));
  return date.getUTCFullYear() === annee
    && date.getUTCMonth() === mois - 1
    && date.getUTCDate() === jour;
};
const estRenseigne = (valeur) => {
  const texte = String(valeur || '').trim();
  return Boolean(texte) && !['à définir', 'a definir', 'n/a', '-'].includes(texte.toLocaleLowerCase('fr-FR'));
};

return $input.all().map((item) => {
  const proposition = item.json || {};
  const manques = [];

  if (proposition.type === 'action') {
    if (!estRenseigne(proposition.tache)) manques.push('tâche');
    if (!estRenseigne(proposition.responsable)) manques.push('responsable');
    if (!estDateISOValide(proposition.echeance)) manques.push('échéance YYYY-MM-DD valide');
  } else if (proposition.type === 'decision') {
    if (!estRenseigne(proposition.texte)) manques.push('texte de la décision');
  } else {
    manques.push('type ACTION ou DECISION reconnu');
  }

  const pret = manques.length === 0;
  return {
    json: {
      ...proposition,
      etat_validation: pret ? 'prêt à valider' : 'à compléter',
      champs_a_completer: manques,
      action_suivante: pret
        ? 'Validation humaine requise avant toute création de tâche.'
        : 'Compléter les champs listés ; aucune tâche ne sera créée.',
      creation_reelle: false
    }
  };
});
